import test from 'node:test';import assert from 'node:assert/strict';import {correctProductData} from './product-title-corrections.mjs';
import {reviewedPublicationVariation} from './product-deduplication.mjs';
test('novo título da Kappa mantém a identidade estrita da variante',()=>{
  const p={id:'mWlmlmg15okWqGyIc5bh',titulo:'Tênis Kappa Pulse RX unissex — anúncio MLB5532075156',link:'https://produto.mercadolivre.com.br/MLB-5532075156-_JM?searchVariation=200557607873',linkAfiliado:'https://meli.la/1ipvXiB'};
  assert.equal(reviewedPublicationVariation(p)?.variationId,'200557607873');
  assert.equal(reviewedPublicationVariation({...p,link:p.link.replace('200557607873','200557607865')}),null);
  assert.equal(reviewedPublicationVariation({...p,linkAfiliado:'https://meli.la/outro'}),null);
});
test('triagem115 preserva dados operacionais',()=>{for(const [id,titulo,expected,link] of [["mlMLB7871750870","Microfone Lapela A'Gold MCF-38D Sem Fio para iPhone e Android com 2 Microfones","A’Gold MCF-38D — kit sem fio com dois microfones de lapela","https://www.mercadolivre.com.br/p/MLB53816127?wid=MLB7871750870"],["mWlmlmg15okWqGyIc5bh","Tênis Kappa Pulse Rx Unissex Corrida Conforto","Tênis Kappa Pulse RX unissex — anúncio MLB5532075156","https://produto.mercadolivre.com.br/MLB-5532075156-tnis-kappa-pulse-rx-unissex-corrida-conforto-_JM?searchVariation=200557607873"],["n4IIyDvWZZGMKhBisDSq","Lavadora De Alta Pressão Profissional Wap 4100 W2 420l/h Motor De Indução 1650psi 1500w 127V","Lavadora WAP 4100 W2 — variante 127 V anunciada","https://www.mercadolivre.com.br/p/MLB69473763?pdp_filters=item_id%3AMLB6842727330"]]){const p={id,titulo,link,preco:'preservar',linkAfiliado:'https://meli.la/preservar'},x=correctProductData(p);assert.ok(x.comentario.length>=180);for(const k of ['id','preco','linkAfiliado','link'])assert.equal(x[k],p[k]);assert.equal(x.titulo,expected);assert.deepEqual(correctProductData(x),x);assert.equal(correctProductData({...p,link:'https://produto.mercadolivre.com.br/MLB-123'}).titulo,titulo);}});
